#include <stdio.h>

void showDouble(int x) {
    printf("%d\n", x * 2);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int i;
    for (i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 1;
        }
        showDouble(x);
    }
    return 0;
}
